Here is a Python implementation of the Template Method pattern for sorting:

```python
from abc import ABC, abstractmethod
from typing import List, Any

class SortAlgorithm(ABC):
    def __init__(self, data: List[Any]):
        self.data = data.copy()

    # Template method - defines the skeleton
    def sort(self) -> List[Any]:
        n = len(self.data)
        for i in range(n):
            for j in range(i + 1, n):
                if self.compare(self.data[i], self.data[j]):
                    self.swap(i, j)
        return self.data

    @abstractmethod
    def compare(self, a: Any, b: Any) -> bool:
        """Return True if a should come after b"""
        pass

    @abstractmethod
    def swap(self, i: int, j: int) -> None:
        """Swap elements at i and j"""
        pass


class BubbleSort(SortAlgorithm):
    def compare(self, a, b):
        return a > b

    def swap(self, i, j):
        self.data[i], self.data[j] = self.data[j], self.data[i]

    # Concrete algorithm override
    def sort(self) -> List[Any]:
        n = len(self.data)
        for i in range(n):
            swapped = False
            for j in range(0, n - i - 1):
                if self.compare(self.data[j], self.data[j + 1]):
                    self.swap(j, j + 1)
                    swapped = True
            if not swapped:
                break
        return self.data


class SelectionSort(SortAlgorithm):
    def compare(self, a, b):
        return a > b

    def swap(self, i, j):
        self.data[i], self.data[j] = self.data[j], self.data[i]

    def sort(self) -> List[Any]:
        n = len(self.data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(self.data[min_idx], self.data[j]):
                    min_idx = j
            if min_idx != i:
                self.swap(i, min_idx)
        return self.data


# Test
if __name__ == "__main__":
    ints = [64, 25, 12, 22, 11]
    strs = ["banana", "apple", "cherry", "date"]

    print("BubbleSort ints:", BubbleSort(ints).sort())
    print("SelectionSort ints:", SelectionSort(ints).sort())
    print("BubbleSort strs:", BubbleSort(strs).sort())
    print("SelectionSort strs:", SelectionSort(strs).sort())
```

The abstract `SortAlgorithm` defines the template with `compare` and `swap`. `BubbleSort` and `SelectionSort` provide their own algorithm implementations while reusing the common comparison/swapping primitives.

